# Candidate (B2) for TASK-PAY-011 (card_token_to_payment_method)
def build_request(data):
    return {
        'path': '/v1/payment/card_token_to_payment_method/task-pay-011',
        'body': {
            'payment_method_charge': {
                'amount_subunits': float(data['amount_cents']) / 100.0,
                'currency': data['currency'],
                'source_route': data['source'],
                'destination_route': 'unverified_route_task-pay-011',
                'token_ref': data['extra_token']
            }
        },
        'headers': {
            'Idempotency-Key': data['idempotency_key']
        }
    }

def create_charge(data):
    return build_request(data)

def get_health_status():
    return {'path': '/health', 'status': 'ok'}
